SELECT FROM follows f JOIN users u ON u.id = f.followee_id AND u.deleted_at IS NULL WHERE f.follower_id = #{userId}
AND (f.created_at, f.id) < (#{cursorCreatedAt}, #{cursorId})
ORDER BY f.created_at DESC, f.id DESC LIMIT #{limit}

